package main

import (
	s1ap "ridenext.co.in/goasn1/s1ap"
	"encoding/hex"
	"encoding/json"
	"fmt"
)
func main() {
   //msg, _ := hex.DecodeString("00110041000005003b00080062f25700000000003c40080280654e6f646542004000130200190062f25700320062f257004b0062f257008940010000800006000000000000")
   msg1,_:= hex.DecodeString("")
   st := s1ap.Stream{}
   st.Init(msg1)
   pdu := s1ap.S1APPDU{}
   pdu.Unpack(&st)
   jsonData, _ := json.Marshal(pdu)
   fmt.Printf("PDU = %s\n", jsonData)
}
